/**
 * MCA v0.1 conformance tests against test/vectors/ (regenerated by
 * gen-vectors.js immediately before this file runs, via `npm test`).
 */

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { verifyRecord, verifyChain, verifyCheckpoint, verifyInclusion } from "../src/verify.js";

const vectors = join(dirname(fileURLToPath(import.meta.url)), "vectors");
const readJson = (n) => JSON.parse(readFileSync(join(vectors, n), "utf8"));
const readJsonl = (n) =>
  readFileSync(join(vectors, n), "utf8").split("\n").filter((l) => l.trim()).map((l) => JSON.parse(l));

const chain = readJsonl("chain-valid.jsonl");
const checkpoint = readJson("checkpoint-valid.json");
const forgedCp = readJson("checkpoint-forged.json");
const pubPem = readFileSync(join(vectors, "log.pub.pem"), "utf8");
const inclusionRecord = readJson("inclusion-record.json");
const inclusionPath = readJson("inclusion-path.json");

test("valid chain is VALID", () => {
  const r = verifyChain(chain);
  assert.equal(r.result, "VALID", r.reasons.join("; "));
});

test("tampered chain is INVALID with a broken-link reason", () => {
  const r = verifyChain(readJsonl("chain-tampered.jsonl"));
  assert.equal(r.result, "INVALID");
  assert.ok(
    r.reasons.some((x) => x.startsWith("broken-link")),
    `expected broken-link reason, got: ${r.reasons.join("; ")}`,
  );
});

test("gap in sequence is detected", () => {
  const r = verifyChain(readJsonl("chain-gap.jsonl"));
  assert.equal(r.result, "INVALID");
  assert.ok(
    r.reasons.some((x) => x.startsWith("gap:")),
    `expected gap reason, got: ${r.reasons.join("; ")}`,
  );
});

test("record plus matching evidence is VALID", () => {
  const r = verifyRecord(inclusionRecord, readJson("evidence-3.json"));
  assert.equal(r.result, "VALID", r.reasons.join("; "));
});

test("record plus wrong evidence is INVALID", () => {
  const wrong = { rail_receipt: { rail: "x402", tx: "0xFFFF", amount: "999.00", currency: "USD" } };
  const r = verifyRecord(inclusionRecord, wrong);
  assert.equal(r.result, "INVALID");
  assert.ok(r.reasons.some((x) => x.startsWith("evidence-mismatch")));
});

test("checkpoint verifies via ed25519 and surfaces UNWITNESSED", () => {
  const r = verifyCheckpoint(checkpoint, chain, null, pubPem);
  assert.equal(r.result, "VALID", r.reasons.join("; "));
  assert.ok(r.reasons.some((x) => x.startsWith("UNWITNESSED")), `missing UNWITNESSED caveat: ${r.reasons}`);
});

test("forged checkpoint (wrong merkle_root, original signature) is INVALID", () => {
  const r = verifyCheckpoint(forgedCp, chain, null, pubPem);
  assert.equal(r.result, "INVALID");
  assert.ok(
    r.reasons.some((x) => x === "merkle-root-mismatch") || r.reasons.some((x) => x.startsWith("bad-signature")),
    `expected merkle/signature failure, got: ${r.reasons.join("; ")}`,
  );
});

test("inclusion proof against the real checkpoint root is VALID", () => {
  const r = verifyInclusion(inclusionRecord, inclusionPath, checkpoint);
  assert.equal(r.result, "VALID", r.reasons.join("; "));
});

test("inclusion proof against the forged root is INVALID", () => {
  const r = verifyInclusion(inclusionRecord, inclusionPath, forgedCp);
  assert.equal(r.result, "INVALID");
  assert.ok(r.reasons.some((x) => x.startsWith("inclusion-proof-failed")));
});

test("invalid subject_type is INVALID", () => {
  const bad = JSON.parse(JSON.stringify(inclusionRecord));
  bad.subject_type = "robot";
  const r = verifyRecord(bad);
  assert.equal(r.result, "INVALID");
  assert.ok(r.reasons.some((x) => x.startsWith("bad-subject_type")));
});
